node -v && node --input-type=module -e '
import {createPushGate} from "./bot.mjs";
import assert from "node:assert";
const u={id:"u_8841",timeZone:"Asia/Tokyo",quietStart:"22:00",quietEnd:"07:00",dailyCap:3};
const d=s=>new Date(s);
let g=createPushGate();
// Tokyo 12:00 = 03:00Z
assert.deepEqual(g.attempt(u,d("2026-10-23T03:00:00Z")),{allowed:true,reason:null});
// Tokyo 22:00 start inclusive (13:00Z), 07:00 end exclusive (22:00Z prev)
assert.equal(createPushGate().attempt(u,d("2026-10-23T13:00:00Z")).reason,"quiet_hours");
assert.equal(createPushGate().attempt(u,d("2026-10-23T12:59:00Z")).allowed,true);
assert.equal(createPushGate().attempt(u,d("2026-10-22T21:59:00Z")).reason,"quiet_hours");
assert.equal(createPushGate().attempt(u,d("2026-10-22T22:00:00Z")).allowed,true);
// cap: 3 allowed, 4th blocked, refused ones do not count, quiet ones do not count
g=createPushGate();
for(const h of ["01","02","03"]) assert.equal(g.attempt(u,d(`2026-10-23T${h}:00:00Z`)).allowed,true);
assert.equal(g.attempt(u,d("2026-10-23T04:00:00Z")).reason,"daily_cap_reached");
// local midnight in Tokyo = 15:00Z: next local day resets
assert.equal(g.attempt(u,d("2026-10-23T14:59:00Z")).reason,"daily_cap_reached");
// 15:00Z is 00:00 Tokyo -> quiet; 22:00Z = 07:00 next day Tokyo -> allowed, new day
assert.equal(g.attempt(u,d("2026-10-23T22:00:00Z")).allowed,true);
// UTC midnight must not reset a Tokyo day
g=createPushGate();
for(const h of ["22","23"]) g.attempt(u,d(`2026-10-22T${h}:00:00Z`)); // 07:00,08:00 Tokyo 23rd
g.attempt(u,d("2026-10-23T00:30:00Z"));
assert.equal(g.attempt(u,d("2026-10-23T01:00:00Z")).reason,"daily_cap_reached");
// other user independent, bad zone held, cap 0
assert.equal(g.attempt({...u,id:"x"},d("2026-10-23T01:00:00Z")).allowed,true);
assert.equal(g.attempt({...u,id:"y",timeZone:"Nope/Zone"},d("2026-10-23T01:00:00Z")).reason,"invalid_time_zone");
assert.equal(g.attempt({...u,id:"z",dailyCap:0},d("2026-10-23T01:00:00Z")).reason,"daily_cap_reached");
// DST: New York fall back 2026-11-01; 06:30 local EST = 11:30Z, EDT 06:30 = 10:30Z
const ny={id:"n",timeZone:"America/New_York",quietStart:"22:00",quietEnd:"07:00",dailyCap:5};
assert.equal(createPushGate().attempt(ny,d("2026-11-01T11:30:00Z")).reason,"quiet_hours");
assert.equal(createPushGate().attempt(ny,d("2026-11-01T12:00:00Z")).allowed,true);
console.log("ok");
'

